import { useEffect, useMemo, useState } from 'react'
import { CalendarDays, ChevronLeft, ChevronRight, CircleSlash2 } from 'lucide-react'
import { ExecutionLedger } from '../components/ExecutionLedger'
import { useApp } from '../state/AppContext'
import { dateLabel, number, signedMoney } from '../utils/format'

const monthKey = (date: Date) => `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, '0')}`
const fromMonthKey = (key: string) => {
  const [year, month] = key.split('-').map(Number)
  return new Date(Date.UTC(year, month - 1, 1))
}

export const CalendarView = () => {
  const { analysis, calendarBasis, setCalendarBasis, filters, setFilters } = useApp()
  const days = calendarBasis === 'tradeDate' ? analysis?.calendarTrade ?? [] : analysis?.calendarSettlement ?? []
  const latest = days.at(-1)?.date.slice(0, 7) ?? monthKey(new Date())
  const selectedDates = useMemo(() => Array.from(new Set([filters.dateFrom, filters.dateTo].filter(Boolean))).sort(), [filters.dateFrom, filters.dateTo])
  const [month, setMonth] = useState(latest)
  useEffect(() => { if (!selectedDates.length) setMonth(latest) }, [latest, selectedDates.length])
  const date = fromMonthKey(month)
  const year = date.getUTCFullYear()
  const monthIndex = date.getUTCMonth()
  const totalDays = new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate()
  const leading = date.getUTCDay()
  const byDate = useMemo(() => new Map(days.map(day => [day.date, day])), [days])
  const monthDays = days.filter(day => day.date.startsWith(month))
  const resolvedDays = monthDays.filter(day => day.settledTrades > 0)
  const monthlyPnl = monthDays.reduce((total, day) => total + day.pnl, 0)
  const dailyWinRate = resolvedDays.length ? resolvedDays.filter(day => day.pnl > 0).length / resolvedDays.length : null
  const selectedTrades = analysis?.trades ?? []
  const settledSelectedTrades = selectedTrades.filter(trade => trade.netPnl !== null)
  const selectedPnl = settledSelectedTrades.reduce((total, trade) => total + (trade.netPnl ?? 0), 0)
  const selectedMarkets = new Set(selectedTrades.map(trade => trade.marketTicker)).size
  const pendingSelectedTrades = selectedTrades.filter(trade => trade.source === 'polymarket' ? (trade.openAmount ?? 0) > 0 || Boolean(trade.accountingWarning) : !trade.settled).length
  const monthlyPendingTrades = monthDays.reduce((total, day) => total + (day.pendingTrades ?? day.trades - day.settledTrades), 0)
  const navigate = (offset: number) => setMonth(monthKey(new Date(Date.UTC(year, monthIndex + offset, 1))))

  const applySelectedDates = (values: string[]) => {
    const ordered = [...values].sort()
    setFilters({
      ...filters,
      dateFrom: ordered[0] ?? '',
      dateTo: ordered.length === 1 ? ordered[0] : ordered[1] ?? '',
      dateBasis: calendarBasis
    })
  }

  const selectDay = (day: number) => {
    const value = `${month}-${String(day).padStart(2, '0')}`
    if (selectedDates.includes(value)) {
      applySelectedDates(selectedDates.filter(selected => selected !== value))
      return
    }
    applySelectedDates(selectedDates.length >= 2 ? [value] : [...selectedDates, value])
  }

  const clearPeriod = () => applySelectedDates([])
  const changeBasis = (basis: typeof calendarBasis) => {
    setCalendarBasis(basis)
    if (selectedDates.length) setFilters({ ...filters, dateBasis: basis })
  }
  const selectedStart = selectedDates[0] ?? ''
  const selectedEnd = selectedDates[1] ?? selectedStart
  const periodLabel = selectedDates.length === 2
    ? `${dateLabel(selectedStart)} — ${dateLabel(selectedEnd)}`
    : selectedDates.length ? dateLabel(selectedStart) : ''
  const rawMonthLabel = new Intl.DateTimeFormat('pt-BR', { month: 'long', year: 'numeric', timeZone: 'UTC' }).format(date)
  const monthLabel = `${rawMonthLabel.charAt(0).toLocaleUpperCase('pt-BR')}${rawMonthLabel.slice(1)}`

  return (
    <div className='view-stack view-enter'>
      <section className='panel calendar-panel'>
        <div className='calendar-toolbar'>
          <button className='icon-button' type='button' onClick={() => navigate(-1)} aria-label='Mês anterior'><ChevronLeft /></button>
          <div className='calendar-title'>
            <span className='eyebrow'>CALENDÁRIO OPERACIONAL</span>
            <h2>{monthLabel}</h2>
            <p><strong className={!resolvedDays.length ? '' : monthlyPnl >= 0 ? 'positive' : 'negative'}>{resolvedDays.length ? signedMoney(monthlyPnl) : monthlyPendingTrades ? 'PnL pendente' : 'Sem resultado realizado'}</strong><span>{number(monthDays.length)} dias negociados</span><span>{dailyWinRate === null ? '—' : `${number(dailyWinRate * 100, 0)}%`} de dias positivos</span></p>
          </div>
          <button className='icon-button' type='button' onClick={() => navigate(1)} aria-label='Próximo mês'><ChevronRight /></button>
        </div>
        <div className='segmented calendar-basis' aria-label='Base do calendário'>
          <button type='button' className={calendarBasis === 'tradeDate' ? 'active' : ''} onClick={() => changeBasis('tradeDate')}>Data da execução</button>
          <button type='button' className={calendarBasis === 'settlementDate' ? 'active' : ''} onClick={() => changeBasis('settlementDate')}>Data da liquidação</button>
        </div>
        <div className='calendar-grid calendar-weekdays' aria-hidden='true'>{['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'].map(day => <span key={day}>{day}</span>)}</div>
        <div className='calendar-grid' aria-label={`Calendário de ${monthLabel}`}>
          {Array.from({ length: leading }).map((_, index) => <span className='calendar-blank' key={`blank-${index}`} />)}
          {Array.from({ length: totalDays }).map((_, index) => {
            const day = index + 1
            const key = `${month}-${String(day).padStart(2, '0')}`
            const aggregate = byDate.get(key)
            const active = selectedDates.includes(key)
            const inRange = selectedDates.length === 2 && key >= selectedStart && key <= selectedEnd
            const resolved = Boolean(aggregate?.settledTrades)
            const pending = aggregate ? aggregate.pendingTrades ?? aggregate.trades - aggregate.settledTrades : 0
            return (
              <button
                type='button'
                key={key}
                className={`calendar-day ${resolved ? aggregate!.pnl >= 0 ? 'calendar-day--positive' : 'calendar-day--negative' : pending ? 'calendar-day--pending' : ''} ${inRange ? 'calendar-day--in-range' : ''} ${active ? 'calendar-day--selected' : ''}`}
                onClick={() => selectDay(day)}
                aria-pressed={active}
                aria-label={`${dateLabel(key)}${aggregate ? `, ${resolved ? signedMoney(aggregate.pnl) : pending ? 'PnL pendente' : 'sem resultado realizado'}, ${aggregate.trades} fills` : ', sem atividade'}${active ? ', limite selecionado' : inRange ? ', dentro do período' : ''}`}
              >
                <span className='calendar-day__number'>{day}</span>
                {aggregate ? <><strong>{resolved ? signedMoney(aggregate.pnl, true) : pending ? 'Pendente' : '—'}</strong><span>{number(aggregate.trades)} fills{pending > 0 ? ` · ${number(pending)} pendentes` : ''}</span></> : <span className='calendar-day__empty'>—</span>}
              </button>
            )
          })}
        </div>
      </section>
      {selectedDates.length > 0 && (
        <>
          <section className='panel selected-day' aria-live='polite'>
            <CalendarDays aria-hidden='true' />
            <div><span className='eyebrow'>PERÍODO SELECIONADO</span><h2>{periodLabel}</h2><p>{number(selectedTrades.length)} fills em {number(selectedMarkets)} mercados · {settledSelectedTrades.length ? signedMoney(selectedPnl) : pendingSelectedTrades ? 'PnL pendente' : 'Sem resultado realizado'}{pendingSelectedTrades > 0 ? ` · ${number(pendingSelectedTrades)} com resultado pendente` : ''}</p></div>
            <button className='button button--ghost' type='button' onClick={clearPeriod}>Remover filtro do período</button>
          </section>
          <section className='panel calendar-trades'>
            <div className='section-heading'><h2>Execuções</h2><p>{number(selectedTrades.length)} fills no período</p></div>
            <ExecutionLedger trades={selectedTrades} ariaLabel='Execuções do período selecionado' initialSort='time-asc' />
          </section>
        </>
      )}
      {!monthDays.length && <div className='empty-state'><CircleSlash2 aria-hidden='true' /><h3>Sem atividade neste mês</h3><p>Navegue para outro período ou remova os filtros globais.</p></div>}
    </div>
  )
}
